<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import api from '@/js/http/api'

const rows = ref([]), active = ref(null), jobs = ref([]), filters = ref({ rankings: {}, categories: {} })
const metrics = ref({ products: 0, offers: 0, complete: 0, pending: 0, requests: 0 })
const q = ref(''), source = ref(''), ranking = ref(''), category = ref(''), mode = ref('requests')
const brandFilter = ref(''), specFilter = ref(''), candidateFilter = ref('')
const page = ref(1), pages = ref(1), count = ref(0), loading = ref(false), error = ref(''), selectedOffer = ref(null)
let listRequest = 0, detailRequest = 0
const isSourcing = computed(() => mode.value === 'requests')
const offers = computed(() => (isSourcing.value ? active.value?.candidates || [] : active.value?.offers || []).filter(offer =>
  (!brandFilter.value || (brandFilter.value.startsWith('suspected-') ? offer.evidence?.brandRelation === 'unknown' && offer.evidence?.brandEvidence?.clueRelation === brandFilter.value.slice(10) : offer.evidence?.brandRelation === brandFilter.value)) &&
  (!candidateFilter.value || (candidateFilter.value === 'admitted' ? offer.admitted : candidateFilter.value === 'planned' ? offer.planned_rank != null : offer.stage === candidateFilter.value)) &&
  (!specFilter.value || (offer.evidence?.targetSpecStatus || 'unknown') === specFilter.value)))
const statusName = value => ({ complete: '已补全', completed: '已完成', pending: '待补全', partial: '部分完成', running: '采集中', paused: '已暂停', stopped: '已停止', failed: '失败' }[value] || value || '未记录')
const sourceName = value => ({ ranking: '榜单', similar: '寻源', manual: '手动' }[value] || '未分类')
const brandName = (value, evidence) => ({ same: '同品牌', different: '不同品牌' }[value] || ({same:'疑似同品牌',different:'疑似不同品牌'}[evidence?.clueRelation] || '品牌待核'))
const fieldName = (offer, key, label) => offer[key] ? (offer.source_stage === 'search' ? `${label}（搜索页）` : label) : (offer.source_stage === 'search' ? `${label}：搜索页未提取，待详情补全` : `${label}：尚未采到`)
const specName = value => ({ included: '包含目标规格', excluded: '不包含目标规格 / 有冲突' }[value] || '目标规格待核')
const stageName = value => ({ priority: '优先候选', review: '待核对', excluded: '已排除', unassessed: '待重新评估' }[value] || '待重新评估')
const date = value => value ? new Date(value).toLocaleString('zh-CN') : ''
function safe(value) { try { const url = new URL(value); return ['http:', 'https:'].includes(url.protocol) ? url.href : '' } catch { return '' } }
function image(value) { return /^data:image\/(?:jpeg|png|webp|gif);base64,[A-Za-z0-9+/=\r\n]+$/.test(value || '') ? value : safe(value) }
function cover(row) { return isSourcing.value ? image(row.reference?.image) : safe(row.images?.[0]) }
function attributeText(item) { return `${item.name || item.key || ''}：${item.value || ''}` }
function issues(offer) {
  const comparison = offer.evidence?.specComparison || {}
  return [...(comparison.conflicts || []).map(c => `${c.label}：目标 ${c.expected}；页面 ${(c.actual || []).join(' / ')}`),
    ...(comparison.missing || []).map(c => `${c.label}待核：${c.expected}`)]
}
async function select(row) {
  const request = ++detailRequest
  selectedOffer.value = null; active.value = null; brandFilter.value = ''; specFilter.value = ''; candidateFilter.value = ''
  try {
    const params = isSourcing.value ? { request_id: row.id } : { id: row.id, view: mode.value }
    const response = await api.get('/api/goods/imagegrab-you/', { params })
    if (request === detailRequest) active.value = response.data.data
  } catch (e) { if (request === detailRequest) error.value = e.response?.data?.message || '读取详情失败' }
}
async function load(reset = false) {
  if (reset) { page.value = 1; active.value = null; selectedOffer.value = null; ++detailRequest }
  const request = ++listRequest
  loading.value = true; error.value = ''
  try {
    const params = { page: page.value, q: q.value, view: mode.value }
    if (!isSourcing.value) Object.assign(params, { source: mode.value === 'ranking' ? 'ranking' : source.value, ranking: ranking.value, category: category.value })
    const { data } = await api.get('/api/goods/imagegrab-you/', { params })
    if (request !== listRequest) return
    rows.value = data.data; pages.value = data.pages; page.value = data.page; count.value = data.count
    if (data.metrics) metrics.value = data.metrics
    if (data.jobs) jobs.value = data.jobs
    if (data.filters) filters.value = data.filters
    const row = rows.value.find(r => r.id === active.value?.id) || rows.value[0]
    if (row) await select(row)
    else { active.value = null; selectedOffer.value = null; ++detailRequest }
  } catch (e) { if (request === listRequest) error.value = e.response?.data?.message || e.response?.data?.detail || '读取失败，请确认管理员登录状态' }
  finally { if (request === listRequest) loading.value = false }
}
watch([source, ranking, category, mode], () => load(true))
onMounted(() => load())
</script>

<template>
  <main class="you-page">
    <header class="you-heading"><div><small>IMAGEGRAB / RESEARCH</small><h1>1688_you</h1><p>围绕原产品查看候选货源，寻找补充资料或可替代的商品。</p></div><button @click="load()" :disabled="loading">{{ loading ? '读取中…' : '刷新' }}</button></header>
    <p v-if="error" class="you-error" role="alert">{{ error }}</p>
    <section class="you-metrics"><div><span>寻源目标</span><strong>{{ metrics.requests }}</strong></div><div><span>货源档案</span><strong>{{ metrics.offers }}</strong></div><div><span>已补全详情</span><strong>{{ metrics.complete }}</strong></div><div><span>待补全 / 部分完成</span><strong>{{ metrics.pending }}</strong></div></section>
    <nav class="you-tabs" aria-label="研究视图"><button v-for="tab in [{key:'requests',label:'寻源目标'},{key:'ranking',label:'榜单商品'},{key:'unassigned',label:'待归属'},{key:'archive',label:'全部档案'}]" :key="tab.key" :class="{chosen:mode === tab.key}" @click="mode=tab.key">{{ tab.label }}</button></nav>
    <p v-if="mode === 'unassigned'" class="you-note">这些历史寻源记录没有保存足够的搜索关联，暂未放入某个原产品的候选中。</p>
    <form class="you-filters" @submit.prevent="load(true)"><input v-model="q" :placeholder="isSourcing ? '搜索原产品、关键词、品牌' : '搜索商品、品牌、类目'" aria-label="搜索"><button>搜索</button>
      <template v-if="!isSourcing"><select v-if="mode === 'archive'" v-model="source" aria-label="商品来源"><option value="">全部来源</option><option value="ranking">榜单</option><option value="similar">寻源</option><option value="manual">手动</option></select><template v-if="mode !== 'unassigned'"><select v-model="ranking" aria-label="榜单类别"><option value="">全部榜单</option><option v-for="(label,key) in filters.rankings" :key="key" :value="key">{{ label }}</option></select><select v-model="category" aria-label="商品大类"><option value="">全部大类</option><option v-for="(label,key) in filters.categories" :key="key" :value="key">{{ label }}</option></select></template></template>
    </form>
    <div class="you-layout"><section class="you-list"><h2>{{ isSourcing ? '原产品 / 搜索输入' : '商品档案' }} <small>{{ count }} 项</small></h2><p v-if="!rows.length" class="you-empty">{{ loading ? '读取中…' : '暂无记录。在插件研究台点击“同步到 1688_you”后刷新。' }}</p>
      <button v-for="row in rows" :key="row.id" class="you-product" :class="{active:row.id === active?.id}" @click="select(row)"><img v-if="cover(row)" :src="cover(row)" alt="" loading="lazy"><div><strong>{{ row.title || '未命名' }}</strong><template v-if="isSourcing"><span>{{ row.criteria?.brand || '目标品牌未提供' }} · {{ row.candidate_count }} 个候选</span><small>{{ row.criteria?.specs || '规格未提供' }} · {{ row.query_count }} 次搜索条件</small></template><template v-else><span>{{ row.brand || '品牌未记录' }} · {{ row.offer_count }} 条货源</span><small>{{ sourceName(row.source_type) }} · {{ row.scope?.rankingLabel || row.category || '范围未记录' }}</small></template></div></button>
      <footer class="you-pagination"><button :disabled="page <= 1 || loading" @click="page--; load()">上一页</button><span>{{ page }} / {{ pages }}</span><button :disabled="page >= pages || loading" @click="page++; load()">下一页</button></footer>
    </section><section class="you-content"><p v-if="!active" class="you-empty">{{ isSourcing ? '选择原产品查看候选货源。' : '选择商品查看研究结果。' }}</p><template v-else>
      <template v-if="isSourcing"><header class="you-target"><img v-if="image(active.reference?.image)" class="you-reference" :src="image(active.reference.image)" alt="用于寻源的原图"><div><h2>{{ active.title }}</h2><dl class="you-criteria"><dt>搜索词</dt><dd>{{ active.criteria?.name || '仅图片寻源' }}</dd><dt>目标品牌</dt><dd>{{ active.criteria?.brand || '未提供' }}</dd><dt>目标规格</dt><dd>{{ [active.criteria?.specs,active.criteria?.model].filter(Boolean).join('；') || '未提供' }}</dd><dt>类目</dt><dd>{{ active.criteria?.category || '未提供' }}</dd></dl><p v-if="!active.reference?.image" class="you-note">历史记录未保存寻源原图。</p><p class="you-note">{{ active.criteria?.matchMode === 'exact' ? '关键条件完全一致' : '允许差异，保留冲突项供核对' }} · 仅核对已提供条件，未知参数不能据此确认一致。</p></div></header><details class="you-queries"><summary>历次搜索条件（{{ active.queries?.length || 1 }}）</summary><p v-for="(query,index) in active.queries || []" :key="index">{{ query.title }} · 品牌 {{ query.criteria?.brand || '未提供' }} · 规格 {{ query.criteria?.specs || '未提供' }}</p></details>
      </template><template v-else><header><h2>{{ active.title }}</h2><p>{{ active.brand || '品牌未记录' }} · {{ active.category || '类目未记录' }}</p><p v-if="active.scope?.rankingLabel">{{ active.scope.rankingLabel }} · {{ active.scope.categoryName }} · 中国</p><a v-if="safe(active.source_url)" :href="safe(active.source_url)" target="_blank" rel="noopener noreferrer">打开来源商品 ↗</a></header><div class="you-images"><a v-for="url in (active.images || []).slice(0,12)" :key="url" :href="safe(url)" target="_blank" rel="noopener noreferrer"><img v-if="safe(url)" :src="safe(url)" alt="商品图片" loading="lazy"></a></div><p v-if="active.specs" class="you-specs">{{ active.specs }}</p></template>
      <h3>候选货源 · {{ offers.length }}<small v-if="isSourcing"> / {{ active.candidates?.length || 0 }}</small></h3>
      <p v-if="isSourcing" class="you-note you-candidate-summary">已读取 {{ active.candidate_counts?.total || 0 }} 个 · 优先 {{ active.candidate_counts?.priority || 0 }} · 待核对 {{ active.candidate_counts?.review || 0 }} · 已排除 {{ active.candidate_counts?.excluded || 0 }} · 待重新评估 {{ active.candidate_counts?.unassessed || 0 }} · 已入池 {{ active.candidate_counts?.admitted || 0 }} · 本轮待核/补全 {{ active.candidate_counts?.planned || 0 }} / {{ active.criteria?.limit || 20 }}。待核对不等于匹配成功；网站不执行采集。</p>
      <div v-if="isSourcing" class="you-filters"><select v-model="candidateFilter" aria-label="候选阶段"><option value="">全部候选</option><option value="planned">本轮前{{ active.criteria?.limit || 20 }}个待核 / 补全</option><option value="priority">优先候选</option><option value="review">待核对</option><option value="excluded">已排除</option><option value="admitted">已加入商品池</option><option value="unassessed">待重新评估</option></select><select v-model="brandFilter" aria-label="品牌关系"><option value="">全部品牌关系</option><option value="same">同品牌</option><option value="different">不同品牌</option><option value="suspected-same">疑似同品牌</option><option value="suspected-different">疑似不同品牌</option><option value="unknown">全部待核品牌</option></select><select v-model="specFilter" aria-label="目标规格状态"><option value="">全部规格状态</option><option value="included">包含目标规格</option><option value="excluded">不包含目标规格 / 有冲突</option><option value="unknown">目标规格待核</option></select></div>
      <p v-if="!offers.length" class="you-note">{{ isSourcing ? '当前条件下没有候选。' : '尚未同步货源。' }}</p>
       <div class="you-offers"><article v-for="offer in offers" :key="offer.id" class="you-offer"><div class="you-offer-top"><a v-if="safe(offer.images?.[0])" :href="safe(offer.url)" target="_blank" rel="noopener noreferrer"><img :src="safe(offer.images[0])" alt="货源主图" loading="lazy"></a><div><strong>{{ offer.title }}</strong><b>{{ offer.price_text ? `${offer.price_text}${offer.source_stage === 'search' ? '（搜索页参考价）' : ''}` : fieldName(offer, 'price_text', '报价') }}</b><span>{{ offer.moq_text || '起订量未记录' }} · {{ offer.sales_text || '销量未提取' }}</span><span>{{ offer.supplier_name ? `${offer.supplier_name}${offer.source_stage === 'search' ? '（搜索页）' : ''}` : fieldName(offer, 'supplier_name', '供应商') }}</span><span>发货地：{{ offer.ship_from || (offer.source_stage === 'search' ? '待详情补全' : '尚未采到') }}</span></div></div>
         <template v-if="isSourcing"><div class="you-tags"><span>{{ stageName(offer.stage) }}</span><span>{{ offer.admitted ? '已入池' : '未入池' }}</span><span v-if="offer.planned_rank != null">待核顺序 {{ offer.planned_rank }}</span><span>{{ brandName(offer.evidence?.brandRelation, offer.evidence?.brandEvidence) }}</span><span :class="offer.evidence?.targetSpecStatus">{{ specName(offer.evidence?.targetSpecStatus) }}</span><span>{{ offer.certificates?.length ? '有资料记录，需核验' : '尚未采集认证资料' }}</span></div><p v-if="offer.evidence?.brandEvidence?.reason" class="you-note">{{ offer.evidence.brandEvidence.reason }}</p><p v-if="offer.field_evidence && Object.keys(offer.field_evidence).length" class="you-note">已从搜索页保存文本恢复：{{ Object.keys(offer.field_evidence).map(key => ({priceText:'报价',salesText:'销量',supplierName:'供应商'}[key] || key)).join('、') }}</p><p v-for="(issue,index) in issues(offer)" :key="index" class="you-issue">{{ issue }}</p><details v-if="offer.evidence?.specComparison?.checks?.length"><summary>规格核对依据</summary><p v-for="(check,index) in offer.evidence.specComparison.checks" :key="index" class="you-note">{{ check.label }}：目标 {{ check.expected }} · {{ {match:'符合',conflict:'冲突',missing:'待核'}[check.status] }} · {{ check.source || '未采集到依据' }}</p></details><details v-if="offer.certificates?.length"><summary>资料记录（{{ offer.certificates.length }}）</summary><p v-for="(cert,index) in offer.certificates" :key="index">{{ cert.type }} {{ cert.number }} · {{ cert.status === 'verified' ? '已核验' : '待核验' }} <a v-if="safe(cert.evidenceUrl)" :href="safe(cert.evidenceUrl)" target="_blank" rel="noopener noreferrer">来源 ↗</a></p></details></template>
        <p class="you-links"><a v-if="safe(offer.url)" :href="safe(offer.url)" target="_blank" rel="noopener noreferrer">打开货源 ↗</a><a v-if="safe(offer.supplier_url)" :href="safe(offer.supplier_url)" target="_blank" rel="noopener noreferrer">供应商 ↗</a><a v-if="safe(offer.customer_service?.url)" :href="safe(offer.customer_service.url)" target="_blank" rel="noopener noreferrer">客服 ↗</a></p><footer><span>{{ statusName(offer.detail_status) }}</span><button @click="selectedOffer = offer">规格与图片（{{ offer.details?.skus?.length || 0 }}）</button></footer></article></div>
      <details v-if="!isSourcing && active.certificates?.length" class="you-certificates"><summary>认证记录（{{ active.certificates.length }}）</summary><p v-for="(cert,index) in active.certificates" :key="index">{{ cert.type }} {{ cert.number }} · {{ cert.status === 'verified' ? '已核验' : '待核验' }}</p></details>
    </template></section></div>
    <details v-if="jobs.length" class="you-jobs"><summary>最近上报的采集状态</summary><article v-for="job in jobs" :key="job.run_id"><strong>{{ statusName(job.status) }}</strong><span>{{ job.done }} / {{ job.total }}，异常 {{ job.failed }}</span><span>{{ job.username }} · {{ date(job.updated_at) }}</span></article><small>此处为点击同步时的状态快照。</small></details>
    <div v-if="selectedOffer" class="you-mask" @click.self="selectedOffer = null"><section class="you-dialog" role="dialog" aria-modal="true" aria-label="货源规格与图片"><header><h2>{{ selectedOffer.title }}</h2><button @click="selectedOffer = null">关闭</button></header><p>{{ selectedOffer.supplier_name }} · {{ selectedOffer.ship_from }}</p><h3>商品属性</h3><div class="you-attributes"><span v-for="(item, index) in selectedOffer.details?.attributes || []" :key="index">{{ attributeText(item) }}</span></div><h3>规格报价</h3><div class="you-sku-table"><table><thead><tr><th>图片</th><th>选项 / 规格</th><th>报价</th><th>库存</th></tr></thead><tbody><tr v-for="(sku, index) in selectedOffer.details?.skus || []" :key="index"><td><a v-if="safe(sku.imageUrl)" :href="safe(sku.imageUrl)" target="_blank" rel="noopener noreferrer"><img :src="safe(sku.imageUrl)" alt="规格图" loading="lazy"></a></td><td>{{ sku.group }} {{ sku.value }}</td><td>{{ sku.priceText || '未显示' }}</td><td>{{ sku.stockText || '未显示' }}</td></tr></tbody></table><p v-if="!selectedOffer.details?.skus?.length">尚未采集到规格报价。</p></div><h3>主图与详情图</h3><div class="you-images you-media"><a v-for="(media, index) in selectedOffer.details?.media || []" :key="index" :href="safe(media.url)" target="_blank" rel="noopener noreferrer"><img v-if="safe(media.url)" :src="safe(media.url)" :alt="media.role || '详情图片'" loading="lazy"><small>{{ media.role }}</small></a></div></section></div>
  </main>
</template>

<style scoped>
